# Hypothesis: a callback protocol with positional-only and keyword-only parameters accepts a class instance and a matching function, and rejects a function without the keyword-only scale parameter and a function requiring an extra keyword-only argument.
from typing import Callable, Protocol, reveal_type


class Scorer(Protocol):
    def __call__(self, value: int, /, *, scale: int = 1) -> int: ...


class Doubler:
    def __call__(self, value: int, /, *, scale: int = 1) -> int:
        return value * 2 * scale


def double_scale(x: int, /, *, scale: int = 1) -> int:
    return x * 2 * scale


def plain(n: int) -> int:
    return n + 1


def needs_tag(v: int, *, tag: str) -> int:
    return v


def apply(fn: Scorer, value: int) -> int:
    return fn(value)


def apply_callable(fn: Callable[[int], int], value: int) -> int:
    return fn(value)


def make_adder(base: int = 10) -> Callable[[int], int]:
    return lambda x: x + base


def try_plain() -> int:
    return apply(plain, 1)  # expect-error


def try_needs_tag() -> str:
    try:
        apply_callable(needs_tag, 1)  # expect-error
    except TypeError:
        return 'missing tag'
    return 'ok'


score_lambda: Callable[[int], int] = lambda v: v * 3
add_ten = make_adder()
add_one = make_adder(1)

reveal_type(apply(Doubler(), 4))
reveal_type(apply(double_scale, 4))
reveal_type(add_ten)
assert apply(Doubler(), 4) == 8
assert apply(double_scale, 4) == 8
assert apply_callable(score_lambda, 2) == 6
assert apply_callable(lambda v: v - 1, 10) == 9
assert add_ten(1) == 11 and add_one(1) == 2
assert try_plain() == 2
assert try_needs_tag() == 'missing tag'
